module dog_walk_min_distance (input clk,input rst_n,input start,input [4:0] shadow_count,input [4:0] lydia_count,input [7:0] shadow_x [0:15],input [7:0] shadow_y [0:15],input [7:0] lydia_x [0:15],input [7:0] lydia_y [0:15],output reg done,output reg [15:0] min_dist_sq);reg [2:0] state;reg [2:0] next_state;always @(posedge clk or negedge rst_n) beginif (!rst_n) beginstate <= 3'b000;min_dist_sq <= 16'b0;done <= 1'b0;end else beginstate <= next_state;endendalways @(*) beginnext_state = state;case (state)3'b000: // IDLEif (start)next_state = 3'b001;elsenext_state = 3'b000;break;3'b001: // LOAD_PATHSnext_state = 3'b010;break;3'b010: // COMPUTE_SEGMENTSnext_state = 3'b011;break;3'b011: // FIND_MIN_DISTnext_state = 3'b100;break;3'b100: // DONEnext_state = 3'b000;done <= 1'b1;break;endcaseendassign done = (state == 3'b100);endmodule